import base64
from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..validators import IsString, IsOneOf


class FileCollectionInterface(BaseInterface):

    def get_scf(self, export_type=None, timeout=120, alias="default"):
        """Get SCF file content

        :param string export_type: configuration, configurationAndRuntimeObjects or runtimeObjects. None means default Admin API behavior.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: string
        :return: file content
        """
        timeout = timestr_to_secs(timeout)
        IsOneOf(None, "configuration", "configurationAndRuntimeObjects", "runtimeObjects").check(export_type)

        parameters = {"exportType": export_type} if export_type else {}
        scf = self.store.get(alias).execute_procedure("generateScf", parameters, timeout)
        return base64.b64decode(scf).decode('utf-8')

    def collect_scf(self, target_file_name, export_type=None, timeout=120, alias="default"):
        """Collect SCF file.

        :param string target_file_name: target SCF filename.
        :param string export_type: configuration, configurationAndRuntimeObjects or runtimeObjects. None means default Admin API behavior.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(target_file_name)
        IsOneOf(None, "configuration", "configurationAndRuntimeObjects", "runtimeObjects").check(export_type)

        parameters = {"exportType": export_type} if export_type else {}
        self.store.get(alias).execute_procedure("generateScf", parameters, timeout, output_file_name=target_file_name)

    def get_raw_alarm_history_file(self, timeout=120, alias="default"):
        """Get raw alarm history file content.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: string
        :return: file content

        :note: Experimental keyword.
        """
        timeout = timestr_to_secs(timeout)

        alarm_history = self.store.get(alias).execute_procedure("getRawAlarmHistory", {}, timeout)
        return base64.b64decode(alarm_history).decode('utf-8')

    def collect_raw_alarm_history_file(self, target_file_name, timeout=120, alias="default"):
        """Collect raw alarm history file.

        :param string target_file_name: target filename.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :note: Experimental keyword.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(target_file_name)

        self.store.get(alias).execute_procedure("getRawAlarmHistory", {}, timeout, output_file_name=target_file_name)

    def get_frequency_history_file(self, dist_name, timeout=120, alias="default"):
        """Get frequency history file content.

        :param string dist_name: SMOD or CLOCK dist name.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: string
        :return: file content
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)

        alarm_history = self.store.get(alias).execute_procedure("getFrequencyHistory", {"targetDN": dist_name}, timeout)
        return base64.b64decode(alarm_history).decode('utf-8')

    def collect_frequency_history_file(self, dist_name, target_file_name, timeout=120, alias="default"):
        """Collect frequency history file.

        :param string dist_name: SMOD or CLOCK dist name.
        :param string target_file_name: target filename.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        IsString().check(target_file_name)

        self.store.get(alias).execute_procedure("getFrequencyHistory", {"targetDN": dist_name}, timeout, output_file_name=target_file_name)

    def collect_pm_files(self, target_file_name, timeout=120, alias="default"):
        """Collect PM files.

        :param string target_file_name: target filename.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(target_file_name)

        self.store.get(alias).execute_infomodel_request("getPmFiles", {}, timeout, output_file_name=target_file_name)
